/**
 * The server looks up the venue and stores its name, address, rating,
 * price level and first photo, so lists render without a Google call.
 * 404 when the squad or the venue does not exist.
 * @summary Save a venue for a squad
 */
export const addFavorite = async (
  squadID: string,
  addFavoriteRequest: AddFavoriteRequest,
  options?: Parameters<typeof fetcher>[1],
): Promise<void> => {
  const getHeaders = (
    h?: NonNullable<RequestInit['headers']>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {}
    if (h instanceof Headers) return Object.fromEntries(h.entries())
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      )
    }
    const headers: Record<string, string | readonly string[]> = {}
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value
    }
    return headers
  }
  return fetcher<void>(getAddFavoriteUrl(squadID), {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(addFavoriteRequest),
  })
}

